use crate::ipc::{IpcError, IpcErrorCode};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs::{self, File};
use std::path::{Path, PathBuf};

const META_LAYOUT_KEY: &str = "__ferryx_meta:layout";
const META_WORKTREE_LAYOUTS_KEY: &str = "__ferryx_meta:worktree_layouts";
const META_LAYOUT_BY_WORKTREE_KEY: &str = "__ferryx_meta:layout_by_worktree";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedWorktree {
    pub path: String,
    pub branch: String,
    pub head: String,
    #[serde(default)]
    pub is_main: bool,
    #[serde(default)]
    pub is_locked: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedTerminalTabState {
    pub primary_session_id: String,
    pub pane_tree: serde_json::Value,
    pub session_ids_by_leaf_id: HashMap<String, String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub active_leaf_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expanded_leaf_id: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedBrowserTabState {
    pub browser_id: String,
    pub url: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub loading: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub can_go_back: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub can_go_forward: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none", alias = "profile")]
    pub profile_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub worktree_path: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub worktree_label: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedTabGroup {
    pub id: String,
    pub tab_ids: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub active_tab_id: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PersistedTab {
    pub id: String,
    pub session_id: String,
    pub label: String,
    pub custom_title: Option<String>,
    pub worktree_path: String,
    pub pane_tree: Option<serde_json::Value>,
    pub session_ids_by_leaf_id: Option<HashMap<String, String>>,
    pub active_leaf_id: Option<String>,
}

impl<'de> Deserialize<'de> for PersistedTab {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct TabHelper {
            id: String,
            #[serde(default)]
            session_id: Option<String>,
            label: String,
            #[serde(default)]
            custom_title: Option<String>,
            #[serde(default)]
            worktree_path: Option<String>,
            #[serde(default)]
            pane_tree: Option<serde_json::Value>,
            #[serde(default)]
            session_ids_by_leaf_id: Option<HashMap<String, String>>,
            #[serde(default)]
            active_leaf_id: Option<String>,
            #[serde(default)]
            kind: Option<String>,
            #[serde(default)]
            pinned: Option<bool>,
            #[serde(default)]
            terminal: Option<PersistedTerminalTabState>,
            #[serde(default)]
            browser: Option<PersistedBrowserTabState>,
            #[serde(default)]
            #[allow(dead_code)]
            expanded_leaf_id: Option<String>,
        }

        let helper = TabHelper::deserialize(deserializer)?;

        if helper.kind.as_deref() == Some("browser") || helper.browser.is_some() {
            let browser = helper.browser;
            let session_id = helper
                .session_id
                .filter(|s| !s.is_empty())
                .or_else(|| browser.as_ref().map(|b| b.browser_id.clone()))
                .unwrap_or_default();

            let custom_title = helper
                .custom_title
                .or_else(|| browser.as_ref().and_then(|b| b.title.clone()));

            let worktree_path = helper
                .worktree_path
                .or_else(|| browser.as_ref().and_then(|b| b.worktree_path.clone()))
                .unwrap_or_default();

            let pane_tree = Some(serde_json::json!({
                "__kind": "browser",
                "pinned": helper.pinned.unwrap_or(false),
                "browser": browser,
            }));

            return Ok(PersistedTab {
                id: helper.id,
                session_id,
                label: helper.label,
                custom_title,
                worktree_path,
                pane_tree,
                session_ids_by_leaf_id: None,
                active_leaf_id: None,
            });
        }

        let session_id = helper
            .session_id
            .filter(|s| !s.is_empty())
            .or_else(|| helper.terminal.as_ref().map(|t| t.primary_session_id.clone()))
            .unwrap_or_default();

        let custom_title = helper.custom_title;
        let worktree_path = helper.worktree_path.unwrap_or_default();

        let pane_tree = helper
            .pane_tree
            .or_else(|| helper.terminal.as_ref().map(|t| t.pane_tree.clone()));

        let session_ids_by_leaf_id = helper
            .session_ids_by_leaf_id
            .or_else(|| helper.terminal.as_ref().map(|t| t.session_ids_by_leaf_id.clone()));

        let active_leaf_id = helper
            .active_leaf_id
            .or_else(|| helper.terminal.as_ref().and_then(|t| t.active_leaf_id.clone()));

        Ok(PersistedTab {
            id: helper.id,
            session_id,
            label: helper.label,
            custom_title,
            worktree_path,
            pane_tree,
            session_ids_by_leaf_id,
            active_leaf_id,
        })
    }
}

impl Serialize for PersistedTab {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        if let Some(ref pt) = self.pane_tree {
            if pt.get("__kind").and_then(|k| k.as_str()) == Some("browser") {
                let mut map = serde_json::Map::new();
                map.insert("id".to_string(), serde_json::Value::String(self.id.clone()));
                map.insert("kind".to_string(), serde_json::Value::String("browser".to_string()));
                map.insert("label".to_string(), serde_json::Value::String(self.label.clone()));
                let pinned = pt.get("pinned").and_then(|v| v.as_bool()).unwrap_or(false);
                map.insert("pinned".to_string(), serde_json::Value::Bool(pinned));
                if let Some(browser_val) = pt.get("browser") {
                    map.insert("browser".to_string(), browser_val.clone());
                }
                if let Some(ref ct) = self.custom_title {
                    map.insert("customTitle".to_string(), serde_json::Value::String(ct.clone()));
                }
                return serde_json::Value::Object(map).serialize(serializer);
            }
        }

        let mut map = serde_json::Map::new();
        map.insert("id".to_string(), serde_json::Value::String(self.id.clone()));
        map.insert("kind".to_string(), serde_json::Value::String("terminal".to_string()));
        map.insert("label".to_string(), serde_json::Value::String(self.label.clone()));
        map.insert("pinned".to_string(), serde_json::Value::Bool(false));

        let term_pane_tree = self.pane_tree.clone().unwrap_or_else(|| {
            serde_json::json!({
                "type": "leaf",
                "leafId": format!("leaf:{}", self.id),
            })
        });

        let term_session_ids = self.session_ids_by_leaf_id.clone().unwrap_or_else(|| {
            let mut m = HashMap::new();
            if !self.session_id.is_empty() {
                m.insert(format!("leaf:{}", self.id), self.session_id.clone());
            }
            m
        });

        let term_active_leaf = self.active_leaf_id.clone().or_else(|| Some(format!("leaf:{}", self.id)));

        let term_state = serde_json::json!({
            "primarySessionId": self.session_id,
            "paneTree": term_pane_tree,
            "sessionIdsByLeafId": term_session_ids,
            "activeLeafId": term_active_leaf,
            "expandedLeafId": serde_json::Value::Null,
        });
        map.insert("terminal".to_string(), term_state);

        // Include legacy fields for v1 compatibility
        if !self.session_id.is_empty() {
            map.insert("sessionId".to_string(), serde_json::Value::String(self.session_id.clone()));
        }
        if let Some(ref ct) = self.custom_title {
            map.insert("customTitle".to_string(), serde_json::Value::String(ct.clone()));
        }
        if !self.worktree_path.is_empty() {
            map.insert("worktreePath".to_string(), serde_json::Value::String(self.worktree_path.clone()));
        }
        if let Some(ref pt) = self.pane_tree {
            map.insert("paneTree".to_string(), pt.clone());
        }
        if let Some(ref sids) = self.session_ids_by_leaf_id {
            map.insert("sessionIdsByLeafId".to_string(), serde_json::to_value(sids).unwrap_or_default());
        }
        if let Some(ref al) = self.active_leaf_id {
            map.insert("activeLeafId".to_string(), serde_json::Value::String(al.clone()));
        }

        serde_json::Value::Object(map).serialize(serializer)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PersistedLayout {
    pub split_mode: String,
    pub primary_tab_id: Option<String>,
    pub secondary_tab_id: Option<String>,
    pub active_tab_id: Option<String>,
    pub tabs: Vec<PersistedTab>,
}

impl<'de> Deserialize<'de> for PersistedLayout {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct LayoutHelper {
            split_mode: String,
            #[serde(default)]
            primary_tab_id: Option<String>,
            #[serde(default)]
            secondary_tab_id: Option<String>,
            #[serde(default)]
            active_tab_id: Option<String>,
            #[serde(default)]
            tabs: Vec<PersistedTab>,
        }

        let helper = LayoutHelper::deserialize(deserializer)?;
        Ok(PersistedLayout {
            split_mode: helper.split_mode,
            primary_tab_id: helper.primary_tab_id,
            secondary_tab_id: helper.secondary_tab_id,
            active_tab_id: helper.active_tab_id,
            tabs: helper.tabs,
        })
    }
}

impl Serialize for PersistedLayout {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        #[derive(Serialize)]
        #[serde(rename_all = "camelCase")]
        struct Helper<'a> {
            split_mode: &'a str,
            #[serde(skip_serializing_if = "Option::is_none")]
            primary_tab_id: &'a Option<String>,
            #[serde(skip_serializing_if = "Option::is_none")]
            secondary_tab_id: &'a Option<String>,
            #[serde(skip_serializing_if = "Option::is_none")]
            active_tab_id: &'a Option<String>,
            tabs: &'a [PersistedTab],
        }

        Helper {
            split_mode: &self.split_mode,
            primary_tab_id: &self.primary_tab_id,
            secondary_tab_id: &self.secondary_tab_id,
            active_tab_id: &self.active_tab_id,
            tabs: &self.tabs,
        }
        .serialize(serializer)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PersistedTerminalSession {
    pub session_id: String,
    pub local_session_id: Option<String>,
    pub backend_session_id: Option<String>,
    pub worktree_path: String,
    pub cwd: String,
    pub last_command: Option<String>,
    pub recent_scrollback: Option<String>,
    pub created_at: u64,
}

impl<'de> Deserialize<'de> for PersistedTerminalSession {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct SessionHelper {
            #[serde(default)]
            session_id: Option<String>,
            #[serde(default)]
            local_session_id: Option<String>,
            #[serde(default)]
            backend_session_id: Option<String>,
            #[serde(default)]
            worktree_path: Option<String>,
            #[serde(default)]
            cwd: Option<String>,
            #[serde(default)]
            last_command: Option<String>,
            #[serde(default)]
            recent_scrollback: Option<String>,
            #[serde(default)]
            created_at: u64,
        }

        let helper = SessionHelper::deserialize(deserializer)?;
        let local_session_id = helper.local_session_id.clone().or_else(|| helper.session_id.clone());
        let backend_session_id = helper.backend_session_id;
        let session_id = helper
            .session_id
            .or(helper.local_session_id)
            .unwrap_or_default();
        let worktree_path = helper
            .worktree_path
            .clone()
            .or_else(|| helper.cwd.clone())
            .unwrap_or_default();
        let cwd = helper
            .cwd
            .or(helper.worktree_path)
            .unwrap_or_default();

        Ok(PersistedTerminalSession {
            session_id,
            local_session_id,
            backend_session_id,
            worktree_path,
            cwd,
            last_command: helper.last_command,
            recent_scrollback: helper.recent_scrollback,
            created_at: helper.created_at,
        })
    }
}

impl Serialize for PersistedTerminalSession {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        let mut map = serde_json::Map::new();
        if let Some(ref lsid) = self.local_session_id {
            map.insert("localSessionId".to_string(), serde_json::Value::String(lsid.clone()));
        } else if !self.session_id.is_empty() {
            map.insert("localSessionId".to_string(), serde_json::Value::String(self.session_id.clone()));
        }
        if let Some(ref bsid) = self.backend_session_id {
            map.insert("backendSessionId".to_string(), serde_json::Value::String(bsid.clone()));
        } else {
            map.insert("backendSessionId".to_string(), serde_json::Value::Null);
        }
        if !self.session_id.is_empty() {
            map.insert("sessionId".to_string(), serde_json::Value::String(self.session_id.clone()));
        }
        map.insert("worktreePath".to_string(), serde_json::Value::String(self.worktree_path.clone()));
        map.insert("cwd".to_string(), serde_json::Value::String(self.cwd.clone()));
        if let Some(ref lc) = self.last_command {
            map.insert("lastCommand".to_string(), serde_json::Value::String(lc.clone()));
        }
        if let Some(ref rs) = self.recent_scrollback {
            map.insert("recentScrollback".to_string(), serde_json::Value::String(rs.clone()));
        }
        map.insert("createdAt".to_string(), serde_json::json!(self.created_at));

        serde_json::Value::Object(map).serialize(serializer)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PersistedWorkspace {
    pub workspace_id: String,
    pub repo_root: PathBuf,
    pub worktrees: Vec<PersistedWorktree>,
    pub active_worktree_path: Option<String>,
    pub layout: PersistedLayout,
    pub terminal_sessions: HashMap<String, PersistedTerminalSession>,
}

impl<'de> Deserialize<'de> for PersistedWorkspace {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct WorkspaceHelper {
            workspace_id: String,
            repo_root: PathBuf,
            #[serde(default)]
            worktrees: Vec<PersistedWorktree>,
            #[serde(default)]
            active_worktree_path: Option<String>,
            #[serde(default)]
            layout: Option<serde_json::Value>,
            #[serde(default)]
            terminal_sessions: HashMap<String, PersistedTerminalSession>,
            #[serde(default)]
            worktree_layouts: Option<serde_json::Value>,
            #[serde(default)]
            layout_by_worktree: Option<serde_json::Value>,
        }

        let helper = WorkspaceHelper::deserialize(deserializer)?;
        let mut terminal_sessions = helper.terminal_sessions;

        let layout: PersistedLayout = if let Some(ref lval) = helper.layout {
            let parsed_layout: PersistedLayout = serde_json::from_value(lval.clone())
                .map_err(serde::de::Error::custom)?;

            // Store any extra layout fields in terminal_sessions meta
            let mut layout_meta = serde_json::Map::new();
            if let Some(tg) = lval.get("tabGroups") {
                layout_meta.insert("tabGroups".to_string(), tg.clone());
            }
            if let Some(tgl) = lval.get("tabGroupLayout") {
                layout_meta.insert("tabGroupLayout".to_string(), tgl.clone());
            }
            if let Some(fg) = lval.get("focusedGroupId") {
                layout_meta.insert("focusedGroupId".to_string(), fg.clone());
            }
            if let Some(lbt) = lval.get("layoutsByTabId") {
                layout_meta.insert("layoutsByTabId".to_string(), lbt.clone());
            }
            if !layout_meta.is_empty() {
                terminal_sessions.insert(
                    META_LAYOUT_KEY.to_string(),
                    PersistedTerminalSession {
                        session_id: META_LAYOUT_KEY.to_string(),
                        local_session_id: None,
                        backend_session_id: None,
                        worktree_path: String::new(),
                        cwd: String::new(),
                        last_command: None,
                        recent_scrollback: Some(serde_json::to_string(&layout_meta).unwrap_or_default()),
                        created_at: 0,
                    },
                );
            }
            parsed_layout
        } else {
            PersistedLayout {
                split_mode: "none".to_string(),
                primary_tab_id: None,
                secondary_tab_id: None,
                active_tab_id: None,
                tabs: Vec::new(),
            }
        };

        if let Some(ref wl) = helper.worktree_layouts {
            terminal_sessions.insert(
                META_WORKTREE_LAYOUTS_KEY.to_string(),
                PersistedTerminalSession {
                    session_id: META_WORKTREE_LAYOUTS_KEY.to_string(),
                    local_session_id: None,
                    backend_session_id: None,
                    worktree_path: String::new(),
                    cwd: String::new(),
                    last_command: None,
                    recent_scrollback: Some(serde_json::to_string(wl).unwrap_or_default()),
                    created_at: 0,
                },
            );
        }

        if let Some(ref lbw) = helper.layout_by_worktree {
            terminal_sessions.insert(
                META_LAYOUT_BY_WORKTREE_KEY.to_string(),
                PersistedTerminalSession {
                    session_id: META_LAYOUT_BY_WORKTREE_KEY.to_string(),
                    local_session_id: None,
                    backend_session_id: None,
                    worktree_path: String::new(),
                    cwd: String::new(),
                    last_command: None,
                    recent_scrollback: Some(serde_json::to_string(lbw).unwrap_or_default()),
                    created_at: 0,
                },
            );
        }

        Ok(PersistedWorkspace {
            workspace_id: helper.workspace_id,
            repo_root: helper.repo_root,
            worktrees: helper.worktrees,
            active_worktree_path: helper.active_worktree_path,
            layout,
            terminal_sessions,
        })
    }
}

impl Serialize for PersistedWorkspace {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        let mut map = serde_json::Map::new();
        map.insert("workspaceId".to_string(), serde_json::Value::String(self.workspace_id.clone()));
        map.insert("repoRoot".to_string(), serde_json::to_value(&self.repo_root).map_err(serde::ser::Error::custom)?);
        map.insert("worktrees".to_string(), serde_json::to_value(&self.worktrees).map_err(serde::ser::Error::custom)?);
        if let Some(ref awp) = self.active_worktree_path {
            map.insert("activeWorktreePath".to_string(), serde_json::Value::String(awp.clone()));
        } else {
            map.insert("activeWorktreePath".to_string(), serde_json::Value::Null);
        }

        // Build layout object including any metadata
        let mut layout_obj = match serde_json::to_value(&self.layout).map_err(serde::ser::Error::custom)? {
            serde_json::Value::Object(m) => m,
            _ => serde_json::Map::new(),
        };

        if let Some(meta_sess) = self.terminal_sessions.get(META_LAYOUT_KEY) {
            if let Some(ref json_str) = meta_sess.recent_scrollback {
                if let Ok(serde_json::Value::Object(meta_map)) = serde_json::from_str::<serde_json::Value>(json_str) {
                    for (k, v) in meta_map {
                        layout_obj.insert(k, v);
                    }
                }
            }
        }
        map.insert("layout".to_string(), serde_json::Value::Object(layout_obj));

        // Filter out internal metadata keys from terminalSessions
        let real_sessions: HashMap<String, PersistedTerminalSession> = self
            .terminal_sessions
            .iter()
            .filter(|(k, _)| !k.starts_with("__ferryx_meta:"))
            .map(|(k, v)| (k.clone(), v.clone()))
            .collect();
        map.insert(
            "terminalSessions".to_string(),
            serde_json::to_value(&real_sessions).map_err(serde::ser::Error::custom)?,
        );

        if let Some(meta_sess) = self.terminal_sessions.get(META_WORKTREE_LAYOUTS_KEY) {
            if let Some(ref json_str) = meta_sess.recent_scrollback {
                if let Ok(v) = serde_json::from_str::<serde_json::Value>(json_str) {
                    map.insert("worktreeLayouts".to_string(), v);
                }
            }
        }

        if let Some(meta_sess) = self.terminal_sessions.get(META_LAYOUT_BY_WORKTREE_KEY) {
            if let Some(ref json_str) = meta_sess.recent_scrollback {
                if let Ok(v) = serde_json::from_str::<serde_json::Value>(json_str) {
                    map.insert("layoutByWorktree".to_string(), v);
                }
            }
        }

        serde_json::Value::Object(map).serialize(serializer)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedWorkspaceSession {
    pub version: u32,
    pub timestamp: u64,
    pub active_workspace_id: String,
    pub workspaces: HashMap<String, PersistedWorkspace>,
}

pub fn save_session_to_path(
    path: &Path,
    session: &PersistedWorkspaceSession,
) -> Result<(), IpcError> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to create directory for session state: {}", e),
            )
        })?;
    }

    let serialized = serde_json::to_string_pretty(session).map_err(|e| {
        IpcError::new(
            IpcErrorCode::ParseError,
            format!("Failed to serialize session state: {}", e),
        )
    })?;

    let tmp_path = path.with_extension("json.tmp");

    // Durable atomic write: write -> sync_all -> rename -> parent fsync
    {
        use std::io::Write;
        let mut file = File::create(&tmp_path).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to create temporary session file: {}", e),
            )
        })?;
        file.write_all(serialized.as_bytes()).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to write session state: {}", e),
            )
        })?;
        file.sync_all().map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to fsync temporary session file: {}", e),
            )
        })?;
    }

    fs::rename(&tmp_path, path).map_err(|e| {
        IpcError::new(
            IpcErrorCode::IoError,
            format!("Failed to atomically rename session state file: {}", e),
        )
    })?;

    // Parent directory fsync
    if let Some(parent) = path.parent() {
        if let Ok(dir_file) = File::open(parent) {
            let _ = dir_file.sync_all();
        }
    }

    Ok(())
}

pub fn load_session_from_path(path: &Path) -> Result<Option<PersistedWorkspaceSession>, IpcError> {
    if !path.exists() {
        return Ok(None);
    }

    let content = fs::read_to_string(path).map_err(|e| {
        IpcError::new(
            IpcErrorCode::IoError,
            format!("Failed to read session state file: {}", e),
        )
    })?;

    match serde_json::from_str::<PersistedWorkspaceSession>(&content) {
        Ok(session) => {
            if !(1..=3).contains(&session.version) {
                eprintln!("Warning: Unsupported session version {}, ignoring.", session.version);
                return Ok(None);
            }
            Ok(Some(session))
        }
        Err(err) => {
            let backup_path = path.with_extension("json.corrupted");
            let _ = fs::rename(path, backup_path);
            eprintln!(
                "Warning: Session state file was corrupted ({}), moved to backup.",
                err
            );
            Ok(None)
        }
    }
}

pub fn clear_session_from_path(path: &Path) -> Result<(), IpcError> {
    if path.exists() {
        fs::remove_file(path).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to remove session state file: {}", e),
            )
        })?;
    }
    Ok(())
}

